import{c as e}from"./app.756eaed4.js";import{_ as i}from"./plugin-vue_export-helper.21dcd24c.js";const a={},n=e('<h1 id="visualizing-dbds-and-psbs-and-advanced-search" tabindex="-1"><a class="header-anchor" href="#visualizing-dbds-and-psbs-and-advanced-search" aria-hidden="true">#</a> Visualizing DBDs and PSBs and advanced search</h1><h2 id="overview" tabindex="-1"><a class="header-anchor" href="#overview" aria-hidden="true">#</a> Overview</h2><p>IMS Explorer for VS Code provides interactive hierarchical visualization of DBDs and PSBs, allowing you to visually navigate database structures and view segment relationships.</p><h2 id="accessing-visualization" tabindex="-1"><a class="header-anchor" href="#accessing-visualization" aria-hidden="true">#</a> Accessing Visualization</h2><h3 id="from-ims-connections-view" tabindex="-1"><a class="header-anchor" href="#from-ims-connections-view" aria-hidden="true">#</a> From IMS Connections View</h3><ol><li>Expand an IMS database connection in the <strong>IMS Connections</strong> view.</li><li>Right-click a DBD or PSB.</li><li>Select <strong>Visualize DBD</strong> or <strong>Visualize PSB</strong>.</li></ol><h3 id="from-ims-projects-view" tabindex="-1"><a class="header-anchor" href="#from-ims-projects-view" aria-hidden="true">#</a> From IMS Projects View</h3><ol><li>Expand an IMS project containing imported DBDs or PSBs.</li><li>Right-click a DBD or PSB file.</li><li>Select <strong>Visualize DBD</strong> or <strong>Visualize PSB</strong>.</li></ol><h2 id="visualization-features" tabindex="-1"><a class="header-anchor" href="#visualization-features" aria-hidden="true">#</a> Visualization Features</h2><h3 id="interactive-navigation" tabindex="-1"><a class="header-anchor" href="#interactive-navigation" aria-hidden="true">#</a> Interactive Navigation</h3><ul><li>Expand segments to view child segments and fields.</li><li>Click segments to highlight and focus on specific areas.</li><li>Navigate hierarchical relationships visually.</li></ul><h3 id="zoom-controls" tabindex="-1"><a class="header-anchor" href="#zoom-controls" aria-hidden="true">#</a> Zoom Controls</h3><ul><li><strong>Zoom In</strong>: Magnify the visualization for detailed inspection.</li><li><strong>Zoom Out</strong>: View the entire structure at once.</li><li><strong>Reset View</strong>: Return to default zoom and position.</li></ul><h3 id="multiple-view-modes" tabindex="-1"><a class="header-anchor" href="#multiple-view-modes" aria-hidden="true">#</a> Multiple View Modes</h3><p>Switch between different views using tabs or context menu:</p><ul><li><strong>Visualization</strong>: Interactive hierarchical diagram.</li><li><strong>Source Code</strong>: View the original source code.</li><li><strong>DDL</strong>: View the Data Definition Language.</li><li><strong>Table</strong>: View segments and fields in tabular format.</li></ul><h2 id="use-cases" tabindex="-1"><a class="header-anchor" href="#use-cases" aria-hidden="true">#</a> Use cases</h2><ul><li>Understand database structure and relationships.</li><li>Navigate complex hierarchies visually.</li><li>Identify segment dependencies and parent-child relationships.</li><li>Review database design before making changes.</li></ul><h2 id="advanced-search" tabindex="-1"><a class="header-anchor" href="#advanced-search" aria-hidden="true">#</a> Advanced search</h2><p>The DBD and PSB table views include an advanced search feature that lets you find related definitions across your IMS catalog.</p><h3 id="finding-referenced-psbs-and-dbds" tabindex="-1"><a class="header-anchor" href="#finding-referenced-psbs-and-dbds" aria-hidden="true">#</a> Finding referenced PSBs and DBDs</h3><ol><li>In the <strong>IMS Connections</strong> view, expand a database connection to display the DBD or PSB table view.</li><li>Select the overflow menu ( <strong>\u22EF</strong> ) for any DBD or PSB entry.</li><li>Choose <strong>Find referenced PSBs</strong> (for a DBD) or <strong>Find referenced DBDs</strong> (for a PSB).</li><li>Results are displayed in a nested table showing all related definitions.</li></ol><h3 id="importing-referenced-dbds-and-psbs-into-ims-projects" tabindex="-1"><a class="header-anchor" href="#importing-referenced-dbds-and-psbs-into-ims-projects" aria-hidden="true">#</a> Importing referenced DBDs and PSBs into IMS projects</h3><p>You can use the advanced search results to import referenced DBDs and PSBs directly into an IMS project.</p><ol><li>Run an advanced search as described above.</li><li>In the results table, select the DBDs or PSBs you want to import.</li><li>Select <strong>Import</strong> to add the selected definitions to your IMS project.</li></ol><p>This lets you quickly populate an IMS project with all the dependencies needed for a given database or program specification block.</p>',26);function s(r,t){return n}var l=i(a,[["render",s]]);export{l as default};
